// Geometry 5 Phase 4 — centralized canonical question bank (Phase 3 bank preserved)
const QUESTION_BANK={"C1":{"id":"C1","level":"core","family":"method","titleEn":"Choose the method","titleId":"Pilih metode","textEn":"For each situation, state the most natural first method. Do not solve: (a) right triangle, legs 6 and 8, find hypotenuse; (b) A=47°, B=68°, a=9, find b; (c) sides 8 and 11 with included angle 50°, find third side; (d) sides 7,9,12, find largest angle; (e) similar triangles with scale factor known, find corresponding side; (f) sides 12 and 15 with included angle 30°, find area.","textId":"Untuk setiap situasi, tentukan metode pertama yang paling alami. Jangan selesaikan: (a) segitiga siku-siku, kaki 6 dan 8, cari sisi miring; (b) A=47°, B=68°, a=9, cari b; (c) sisi 8 dan 11 dengan sudut apit 50°, cari sisi ketiga; (d) sisi 7,9,12, cari sudut terbesar; (e) dua segitiga sebangun dan faktor skala diketahui, cari sisi bersesuaian; (f) sisi 12 dan 15 dengan sudut apit 30°, cari luas.","fields":[{"labelEn":"(a)","labelId":"(a)","type":"select","answer":"pyth","options":[{"value":"pyth","en":"Pythagoras / basic trigonometry","id":"Pythagoras / trigonometri dasar"},{"value":"sine","en":"Sine rule","id":"Aturan sinus"},{"value":"cosine","en":"Cosine rule","id":"Aturan cosinus"},{"value":"similarity","en":"Similarity","id":"Kesebangunan"},{"value":"area","en":"Triangle area ½ab sin C","id":"Luas segitiga ½ab sin C"}]},{"labelEn":"(b)","labelId":"(b)","type":"select","answer":"sine","options":[{"value":"pyth","en":"Pythagoras / basic trigonometry","id":"Pythagoras / trigonometri dasar"},{"value":"sine","en":"Sine rule","id":"Aturan sinus"},{"value":"cosine","en":"Cosine rule","id":"Aturan cosinus"},{"value":"similarity","en":"Similarity","id":"Kesebangunan"},{"value":"area","en":"Triangle area ½ab sin C","id":"Luas segitiga ½ab sin C"}]},{"labelEn":"(c)","labelId":"(c)","type":"select","answer":"cosine","options":[{"value":"pyth","en":"Pythagoras / basic trigonometry","id":"Pythagoras / trigonometri dasar"},{"value":"sine","en":"Sine rule","id":"Aturan sinus"},{"value":"cosine","en":"Cosine rule","id":"Aturan cosinus"},{"value":"similarity","en":"Similarity","id":"Kesebangunan"},{"value":"area","en":"Triangle area ½ab sin C","id":"Luas segitiga ½ab sin C"}]},{"labelEn":"(d)","labelId":"(d)","type":"select","answer":"cosine","options":[{"value":"pyth","en":"Pythagoras / basic trigonometry","id":"Pythagoras / trigonometri dasar"},{"value":"sine","en":"Sine rule","id":"Aturan sinus"},{"value":"cosine","en":"Cosine rule","id":"Aturan cosinus"},{"value":"similarity","en":"Similarity","id":"Kesebangunan"},{"value":"area","en":"Triangle area ½ab sin C","id":"Luas segitiga ½ab sin C"}]},{"labelEn":"(e)","labelId":"(e)","type":"select","answer":"similarity","options":[{"value":"pyth","en":"Pythagoras / basic trigonometry","id":"Pythagoras / trigonometri dasar"},{"value":"sine","en":"Sine rule","id":"Aturan sinus"},{"value":"cosine","en":"Cosine rule","id":"Aturan cosinus"},{"value":"similarity","en":"Similarity","id":"Kesebangunan"},{"value":"area","en":"Triangle area ½ab sin C","id":"Luas segitiga ½ab sin C"}]},{"labelEn":"(f)","labelId":"(f)","type":"select","answer":"area","options":[{"value":"pyth","en":"Pythagoras / basic trigonometry","id":"Pythagoras / trigonometri dasar"},{"value":"sine","en":"Sine rule","id":"Aturan sinus"},{"value":"cosine","en":"Cosine rule","id":"Aturan cosinus"},{"value":"similarity","en":"Similarity","id":"Kesebangunan"},{"value":"area","en":"Triangle area ½ab sin C","id":"Luas segitiga ½ab sin C"}]}],"hintsEn":["Classify the information before thinking about a formula.","Ask whether the triangle is right, SAS, SSS, or contains a complete opposite pair.","For area with two sides and their included angle, ½ab sin C is direct."],"hintsId":["Klasifikasikan informasinya sebelum memikirkan rumus.","Tanyakan apakah segitiganya siku-siku, SAS, SSS, atau memiliki pasangan sisi-sudut berhadapan yang lengkap.","Untuk luas dengan dua sisi dan sudut apit, ½ab sin C adalah jalur langsung."],"wrongEn":"One of the information patterns has been matched to the wrong first method.","wrongId":"Ada pola informasi yang dipasangkan dengan metode pertama yang kurang tepat.","solutionEn":"(a) Pythagoras; (b) sine rule; (c) cosine rule; (d) cosine rule; (e) similarity; (f) ½ab sin C.","solutionId":"(a) Pythagoras; (b) aturan sinus; (c) aturan cosinus; (d) aturan cosinus; (e) kesebangunan; (f) ½ab sin C.","strategyEn":"Method selection","strategyId":"Pemilihan metode"},"C2":{"id":"C2","level":"core","family":"sine-side","titleEn":"Sine rule: missing sides","titleId":"Aturan sinus: mencari sisi","textEn":"In △ABC, A=38°, B=67°, a=7 cm. Find C, b and c.","textId":"Pada △ABC, A=38°, B=67°, a=7 cm. Tentukan C, b, dan c.","fields":[{"labelEn":"C (°)","labelId":"C (°)","type":"number","answer":75,"tol":0.05},{"labelEn":"b (cm)","labelId":"b (cm)","type":"number","answer":10.5,"tol":0.15},{"labelEn":"c (cm)","labelId":"c (cm)","type":"number","answer":11.0,"tol":0.15}],"hintsEn":["Find the third angle first.","Use the complete opposite pair (A,a).","Write only the two sine-rule fractions needed for b and c."],"hintsId":["Cari sudut ketiga terlebih dahulu.","Gunakan pasangan lengkap (A,a).","Tuliskan hanya dua pecahan aturan sinus yang diperlukan untuk b dan c."],"wrongEn":"Check that each side is paired with its opposite angle.","wrongId":"Cek bahwa setiap sisi dipasangkan dengan sudut di depannya.","solutionEn":"C=75°. Then b/sin67°=7/sin38° and c/sin75°=7/sin38°, giving b≈10.5 cm and c≈11.0 cm.","solutionId":"C=75°. Lalu b/sin67°=7/sin38° dan c/sin75°=7/sin38°, sehingga b≈10,5 cm dan c≈11,0 cm.","strategyEn":"Opposite-pair mapping","strategyId":"Pasangan sisi-sudut berhadapan"},"C3":{"id":"C3","level":"core","family":"sine-angle","titleEn":"Sine rule: missing angle","titleId":"Aturan sinus: mencari sudut","textEn":"In △ABC, A=78°, a=14 cm, b=9 cm. Find B and C. Explain why there is only one valid triangle.","textId":"Pada △ABC, A=78°, a=14 cm, b=9 cm. Tentukan B dan C. Jelaskan mengapa hanya ada satu segitiga valid.","fields":[{"labelEn":"B (°)","labelId":"B (°)","type":"number","answer":39.0,"tol":0.2},{"labelEn":"C (°)","labelId":"C (°)","type":"number","answer":63.0,"tol":0.2}],"hintsEn":["Use sinB/b = sinA/a.","After inverse sine, also test 180°−B.","The supplementary B makes A+B exceed 180°, so reject it."],"hintsId":["Gunakan sinB/b = sinA/a.","Setelah invers sinus, uji juga 180°−B.","B suplementer membuat A+B melebihi 180°, jadi harus ditolak."],"wrongEn":"A calculator angle is only a candidate; test the supplementary possibility against the triangle angle sum.","wrongId":"Sudut dari kalkulator baru merupakan kandidat; uji kemungkinan suplementernya terhadap jumlah sudut segitiga.","solutionEn":"B≈39.0°. The supplementary candidate is about 141°, but 78°+141°>180°, so it is invalid. Therefore C≈63.0°.","solutionId":"B≈39,0°. Kandidat suplementernya sekitar 141°, tetapi 78°+141°>180°, jadi tidak valid. Maka C≈63,0°.","strategyEn":"Ambiguous-case validity","strategyId":"Keabsahan kasus dua kemungkinan"},"C4":{"id":"C4","level":"core","family":"cosine-side","titleEn":"Cosine rule: missing side","titleId":"Aturan cosinus: mencari sisi","textEn":"Two sides are 9 cm and 12 cm with included angle 73°. Find the third side.","textId":"Dua sisi panjangnya 9 cm dan 12 cm dengan sudut apit 73°. Tentukan sisi ketiga.","fields":[{"labelEn":"Third side (cm)","labelId":"Sisi ketiga (cm)","type":"number","answer":12.7,"tol":0.15}],"hintsEn":["This is SAS.","Use c²=a²+b²−2ab cosC.","The 73° angle must be the angle between the two known sides."],"hintsId":["Ini adalah SAS.","Gunakan c²=a²+b²−2ab cosC.","Sudut 73° harus merupakan sudut di antara dua sisi yang diketahui."],"wrongEn":"Check that you used the included angle in the cosine rule.","wrongId":"Cek bahwa sudut yang digunakan pada aturan cosinus adalah sudut apit.","solutionEn":"x²=9²+12²−2(9)(12)cos73°, so x≈12.7 cm.","solutionId":"x²=9²+12²−2(9)(12)cos73°, sehingga x≈12,7 cm.","strategyEn":"SAS structure","strategyId":"Struktur SAS"},"C5":{"id":"C5","level":"core","family":"cosine-angle","titleEn":"Cosine rule: angle and classification","titleId":"Aturan cosinus: sudut dan klasifikasi","textEn":"A triangle has sides 7, 10 and 12. Find the largest angle and classify the triangle as acute, right or obtuse.","textId":"Sebuah segitiga memiliki sisi 7, 10, dan 12. Tentukan sudut terbesar lalu klasifikasikan segitiganya sebagai lancip, siku-siku, atau tumpul.","fields":[{"labelEn":"Largest angle (°)","labelId":"Sudut terbesar (°)","type":"number","answer":88.0,"tol":0.25},{"labelEn":"Classification","labelId":"Klasifikasi","type":"select","answer":"acute","options":[{"value":"acute","en":"Acute","id":"Lancip"},{"value":"right","en":"Right","id":"Siku-siku"},{"value":"obtuse","en":"Obtus","id":"Tumpul"}]}],"hintsEn":["The largest angle lies opposite side 12.","Use the cosine rule with 12² on the left.","Compare the result with 90°."],"hintsId":["Sudut terbesar berada di depan sisi 12.","Gunakan aturan cosinus dengan 12² pada ruas kiri.","Bandingkan hasilnya dengan 90°."],"wrongEn":"The opposite side of the angle you calculate must be the largest side, 12.","wrongId":"Sisi di depan sudut yang dihitung harus merupakan sisi terbesar, yaitu 12.","solutionEn":"cosC=(7²+10²−12²)/(2·7·10), so C≈88.0°. Since the largest angle is below 90°, the triangle is acute.","solutionId":"cosC=(7²+10²−12²)/(2·7·10), sehingga C≈88,0°. Karena sudut terbesar kurang dari 90°, segitiganya lancip.","strategyEn":"SSS angle classification","strategyId":"Klasifikasi sudut dari SSS"},"C6":{"id":"C6","level":"core","family":"area","titleEn":"Triangle area","titleId":"Luas segitiga","textEn":"Two sides are 8 cm and 15 cm with included angle 42°. Find the area.","textId":"Dua sisi panjangnya 8 cm dan 15 cm dengan sudut apit 42°. Tentukan luasnya.","fields":[{"labelEn":"Area (cm²)","labelId":"Luas (cm²)","type":"number","answer":40.1,"tol":0.2}],"hintsEn":["The included angle is known.","Use A=½ab sinC.","Keep the calculator in degree mode."],"hintsId":["Sudut apit diketahui.","Gunakan A=½ab sinC.","Pastikan kalkulator dalam mode derajat."],"wrongEn":"Use the angle between the two chosen sides, not another angle in the triangle.","wrongId":"Gunakan sudut di antara dua sisi yang dipilih, bukan sudut lain pada segitiga.","solutionEn":"A=½(8)(15)sin42°≈40.1 cm².","solutionId":"A=½(8)(15)sin42°≈40,1 cm².","strategyEn":"Included-angle area","strategyId":"Luas dengan sudut apit"},"C7":{"id":"C7","level":"core","family":"reverse-area","titleEn":"Reverse area","titleId":"Luas terbalik","textEn":"A triangle has area 36 cm². Two sides enclosing a 60° angle have lengths 8 cm and x cm. Find x.","textId":"Sebuah segitiga memiliki luas 36 cm². Dua sisi yang mengapit sudut 60° panjangnya 8 cm dan x cm. Tentukan x.","fields":[{"labelEn":"x (cm)","labelId":"x (cm)","type":"number","answer":10.392,"tol":0.12}],"hintsEn":["Start from A=½ab sinC.","Substitute the known area, side and included angle.","Solve the remaining linear equation for x."],"hintsId":["Mulai dari A=½ab sinC.","Substitusikan luas, sisi, dan sudut apit yang diketahui.","Selesaikan persamaan linear yang tersisa untuk x."],"wrongEn":"Do not round sin60° too early if you want an accurate final value.","wrongId":"Jangan membulatkan sin60° terlalu awal agar hasil akhirnya tetap akurat.","solutionEn":"36=½(8)x sin60°, so x=6√3≈10.4 cm.","solutionId":"36=½(8)x sin60°, sehingga x=6√3≈10,4 cm.","strategyEn":"Reverse area equation","strategyId":"Persamaan luas terbalik"},"C8":{"id":"C8","level":"core","family":"bearing","titleEn":"Bearing components","titleId":"Komponen bearing","textEn":"A rescue boat travels 20 km on bearing 035°. Find its displacement east and north of its starting point.","textId":"Sebuah kapal penyelamat bergerak 20 km pada bearing 035°. Tentukan perpindahannya ke timur dan ke utara dari titik awal.","fields":[{"labelEn":"East (km)","labelId":"Timur (km)","type":"number","answer":11.5,"tol":0.15},{"labelEn":"North (km)","labelId":"Utara (km)","type":"number","answer":16.4,"tol":0.15}],"hintsEn":["Bearings are measured from North.","East is opposite the bearing angle; North is adjacent.","Use E=d sinβ and N=d cosβ."],"hintsId":["Bearing diukur dari arah Utara.","Komponen timur berada di depan sudut bearing; komponen utara bersebelahan dengannya.","Gunakan E=d sinβ dan N=d cosβ."],"wrongEn":"If you swapped sine and cosine, remember that the bearing angle is measured from North, not East.","wrongId":"Jika sinus dan cosinus tertukar, ingat bahwa sudut bearing diukur dari Utara, bukan Timur.","solutionEn":"E=20sin35°≈11.5 km and N=20cos35°≈16.4 km.","solutionId":"E=20sin35°≈11,5 km dan N=20cos35°≈16,4 km.","strategyEn":"Bearing components","strategyId":"Komponen bearing"},"C9":{"id":"C9","level":"core","family":"elevation","titleEn":"Angle of depression","titleId":"Sudut depresi","textEn":"A cliff is 50 m high. From the top, the angle of depression to a boat is 28°. Find the horizontal distance from the boat to the foot of the cliff.","textId":"Sebuah tebing tingginya 50 m. Dari puncaknya, sudut depresi ke sebuah perahu adalah 28°. Tentukan jarak horizontal perahu ke kaki tebing.","fields":[{"labelEn":"Horizontal distance (m)","labelId":"Jarak horizontal (m)","type":"number","answer":94.0,"tol":0.5}],"hintsEn":["Mark the horizontal reference at the top.","The angle of depression equals the corresponding angle of elevation because the horizontals are parallel.","Use tan28°=50/x."],"hintsId":["Tandai garis horizontal di puncak.","Sudut depresi sama dengan sudut elevasi yang bersesuaian karena garis-garis horizontal sejajar.","Gunakan tan28°=50/x."],"wrongEn":"Measure the angle from a horizontal line, not from the vertical cliff.","wrongId":"Ukur sudut dari garis horizontal, bukan dari tebing vertikal.","solutionEn":"tan28°=50/x, hence x≈94.0 m.","solutionId":"tan28°=50/x, sehingga x≈94,0 m.","strategyEn":"Elevation/depression reference","strategyId":"Acuan elevasi/depresi"},"C10":{"id":"C10","level":"core","family":"bearing","titleEn":"Bearing interpretation","titleId":"Interpretasi bearing","textEn":"A drone travels 16 km from P to Q on bearing 120°. Find (a) the bearing of P from Q, (b) how far east of P Q is, and (c) how far south of P Q is.","textId":"Sebuah drone bergerak 16 km dari P ke Q pada bearing 120°. Tentukan (a) bearing P dari Q, (b) seberapa jauh Q berada di timur P, dan (c) seberapa jauh Q berada di selatan P.","fields":[{"labelEn":"Reverse bearing (°)","labelId":"Bearing balik (°)","type":"number","answer":300,"tol":0.1},{"labelEn":"East (km)","labelId":"Timur (km)","type":"number","answer":13.9,"tol":0.15},{"labelEn":"South (km)","labelId":"Selatan (km)","type":"number","answer":8.0,"tol":0.1}],"hintsEn":["Reverse bearings differ by 180°.","Use E=d sinβ and N=d cosβ.","A negative North component means South."],"hintsId":["Bearing balik berbeda 180°.","Gunakan E=d sinβ dan N=d cosβ.","Komponen Utara yang negatif berarti arah Selatan."],"wrongEn":"Keep the compass convention: bearings are clockwise from North.","wrongId":"Pertahankan konvensi kompas: bearing diukur searah jarum jam dari Utara.","solutionEn":"Reverse bearing=300°. E=16sin120°≈13.9 km. N=16cos120°=−8, so Q is 8.00 km south of P.","solutionId":"Bearing balik=300°. E=16sin120°≈13,9 km. N=16cos120°=−8, jadi Q berada 8,00 km di selatan P.","strategyEn":"Bearing interpretation","strategyId":"Interpretasi bearing"},"H1":{"id":"H1","level":"challenge","family":"multi-triangle","titleEn":"Three sides to a hidden right triangle","titleId":"Tiga sisi menuju segitiga siku-siku tersembunyi","textEn":"AB=13 cm, AC=10 cm, BC=7 cm. The perpendicular from C to AB meets AB at D. Find ∠BAC, AD, CD and the area of △ABC.","textId":"AB=13 cm, AC=10 cm, BC=7 cm. Garis tegak lurus dari C ke AB memotong AB di D. Tentukan ∠BAC, AD, CD, dan luas △ABC.","fields":[{"labelEn":"∠BAC (°)","labelId":"∠BAC (°)","type":"number","answer":32.2,"tol":0.2},{"labelEn":"AD (cm)","labelId":"AD (cm)","type":"number","answer":8.46,"tol":0.08},{"labelEn":"CD (cm)","labelId":"CD (cm)","type":"number","answer":5.33,"tol":0.08},{"labelEn":"Area (cm²)","labelId":"Luas (cm²)","type":"number","answer":34.6,"tol":0.2}],"hintsEn":["Use SSS cosine rule first to find ∠BAC.","Once the angle is known, right triangle ACD becomes available.","AD=10cosA and CD can be found by Pythagoras or 10sinA."],"hintsId":["Gunakan aturan cosinus SSS terlebih dahulu untuk mencari ∠BAC.","Setelah sudut diketahui, segitiga siku-siku ACD dapat digunakan.","AD=10cosA dan CD dapat dicari dengan Pythagoras atau 10sinA."],"wrongEn":"The perpendicular is not an initial shortcut until you have enough information to use the right triangle.","wrongId":"Garis tegak lurus belum langsung menyelesaikan soal sampai informasi untuk segitiga siku-sikunya cukup.","solutionEn":"Cosine rule gives cosA=11/13, so A≈32.2°. Then AD=110/13≈8.46, CD=40√3/13≈5.33, and area=½(13)(CD)=20√3≈34.6 cm².","solutionId":"Aturan cosinus memberi cosA=11/13, sehingga A≈32,2°. Lalu AD=110/13≈8,46, CD=40√3/13≈5,33, dan luas=½(13)(CD)=20√3≈34,6 cm².","strategyEn":"Gateway right triangle","strategyId":"Segitiga siku-siku penghubung"},"H2":{"id":"H2","level":"challenge","family":"ambiguity","titleEn":"Ambiguous sine rule","titleId":"Aturan sinus: dua kemungkinan","textEn":"In △ABC, A=42°, a=7 cm, b=10 cm. Find all possible triangles: B, C and c for each.","textId":"Pada △ABC, A=42°, a=7 cm, b=10 cm. Tentukan semua segitiga yang mungkin: B, C, dan c untuk masing-masing.","fields":[{"labelEn":"B₁ (°)","labelId":"B₁ (°)","type":"number","answer":72.9,"tol":0.25},{"labelEn":"C₁ (°)","labelId":"C₁ (°)","type":"number","answer":65.1,"tol":0.25},{"labelEn":"c₁ (cm)","labelId":"c₁ (cm)","type":"number","answer":9.49,"tol":0.12},{"labelEn":"B₂ (°)","labelId":"B₂ (°)","type":"number","answer":107.1,"tol":0.25},{"labelEn":"C₂ (°)","labelId":"C₂ (°)","type":"number","answer":30.9,"tol":0.25},{"labelEn":"c₂ (cm)","labelId":"c₂ (cm)","type":"number","answer":5.38,"tol":0.12}],"hintsEn":["Use sinB/b=sinA/a.","Inverse sine gives B₁; also test B₂=180°−B₁.","For each valid B, find C by angle sum and then c by sine rule."],"hintsId":["Gunakan sinB/b=sinA/a.","Invers sinus memberi B₁; uji juga B₂=180°−B₁.","Untuk setiap B yang valid, cari C dari jumlah sudut lalu c dengan aturan sinus."],"wrongEn":"Do not stop after the first inverse-sine angle; this dataset has two valid configurations.","wrongId":"Jangan berhenti setelah sudut invers sinus pertama; data ini memiliki dua konfigurasi valid.","solutionEn":"B≈72.9° or 107.1°. The corresponding (C,c) pairs are approximately (65.1°,9.49 cm) and (30.9°,5.38 cm).","solutionId":"B≈72,9° atau 107,1°. Pasangan (C,c) yang bersesuaian kira-kira (65,1°,9,49 cm) dan (30,9°,5,38 cm).","strategyEn":"Two SSA configurations","strategyId":"Dua konfigurasi SSA"},"H3":{"id":"H3","level":"challenge","family":"bearing","titleEn":"Two-stage bearing journey","titleId":"Perjalanan bearing dua tahap","textEn":"A ship sails 18 km from A to B on bearing 040°, then 14 km from B to C on bearing 155°. Find ∠ABC, AC and the bearing of C from A.","textId":"Sebuah kapal berlayar 18 km dari A ke B pada bearing 040°, lalu 14 km dari B ke C pada bearing 155°. Tentukan ∠ABC, AC, dan bearing C dari A.","fields":[{"labelEn":"∠ABC (°)","labelId":"∠ABC (°)","type":"number","answer":65,"tol":0.1},{"labelEn":"AC (km)","labelId":"AC (km)","type":"number","answer":17.5,"tol":0.2},{"labelEn":"Bearing C from A (°)","labelId":"Bearing C dari A (°)","type":"number","answer":86,"tol":0.6}],"hintsEn":["At B, first reverse the bearing from A to B.","The reverse bearing BA is 220°, so the internal angle is 220°−155°.","Use cosine rule for AC, then sine rule for ∠BAC and add it to 040°."],"hintsId":["Di B, cari dahulu bearing balik dari A ke B.","Bearing BA adalah 220°, jadi sudut dalamnya 220°−155°.","Gunakan aturan cosinus untuk AC, lalu aturan sinus untuk ∠BAC dan tambahkan ke 040°."],"wrongEn":"Convert the bearings into the internal triangle angle before using triangle trigonometry.","wrongId":"Ubah bearing menjadi sudut dalam segitiga sebelum menggunakan trigonometri segitiga.","solutionEn":"∠ABC=65°. Cosine rule gives AC≈17.5 km. Then ∠BAC≈46.4°, so the bearing of C from A is about 086°.","solutionId":"∠ABC=65°. Aturan cosinus memberi AC≈17,5 km. Lalu ∠BAC≈46,4°, sehingga bearing C dari A sekitar 086°.","strategyEn":"Bearing-to-triangle conversion","strategyId":"Konversi bearing ke segitiga"},"H4":{"id":"H4","level":"challenge","family":"elevation","titleEn":"Tower between two observers","titleId":"Menara di antara dua pengamat","textEn":"A and B lie on opposite sides of the foot T of a vertical tower. AB=80 m. Angles of elevation are 28° from A and 41° from B. Find AT, BT and the tower height.","textId":"A dan B berada pada sisi berlawanan dari kaki T sebuah menara vertikal. AB=80 m. Sudut elevasi dari A adalah 28° dan dari B adalah 41°. Tentukan AT, BT, dan tinggi menara.","fields":[{"labelEn":"AT (m)","labelId":"AT (m)","type":"number","answer":49.6,"tol":0.25},{"labelEn":"BT (m)","labelId":"BT (m)","type":"number","answer":30.4,"tol":0.25},{"labelEn":"Height (m)","labelId":"Tinggi (m)","type":"number","answer":26.4,"tol":0.25}],"hintsEn":["Let AT=x, so BT=80−x.","Both observers see the same tower height.","Set x tan28°=(80−x)tan41° and solve."],"hintsId":["Misalkan AT=x, sehingga BT=80−x.","Kedua pengamat melihat tinggi menara yang sama.","Bentuk x tan28°=(80−x)tan41° lalu selesaikan."],"wrongEn":"The two right triangles share the same vertical height; use that equality rather than solving them separately.","wrongId":"Dua segitiga siku-siku berbagi tinggi vertikal yang sama; gunakan kesamaan itu daripada menyelesaikannya secara terpisah.","solutionEn":"AT≈49.6 m, BT≈30.4 m and height≈26.4 m.","solutionId":"AT≈49,6 m, BT≈30,4 m, dan tinggi≈26,4 m.","strategyEn":"Shared-height equations","strategyId":"Persamaan tinggi yang sama"},"H5":{"id":"H5","level":"challenge","family":"multi-triangle","titleEn":"Quadrilateral by two triangles","titleId":"Segiempat dari dua segitiga","textEn":"Diagonal AC divides quadrilateral ABCD. AB=9, BC=12, ∠ABC=50°, AD=11, CD=8. Find AC, ∠ADC and the total area.","textId":"Diagonal AC membagi segiempat ABCD. AB=9, BC=12, ∠ABC=50°, AD=11, CD=8. Tentukan AC, ∠ADC, dan luas total.","fields":[{"labelEn":"AC","labelId":"AC","type":"number","answer":9.28,"tol":0.12},{"labelEn":"∠ADC (°)","labelId":"∠ADC (°)","type":"number","answer":55.8,"tol":0.25},{"labelEn":"Total area","labelId":"Luas total","type":"number","answer":77.8,"tol":0.4}],"hintsEn":["Triangle ABC is solvable first by SAS.","The diagonal AC becomes the gateway side for triangle ADC.","Use cosine rule for ∠ADC, then add the two triangle areas."],"hintsId":["Segitiga ABC dapat diselesaikan lebih dulu dengan SAS.","Diagonal AC menjadi sisi penghubung untuk segitiga ADC.","Gunakan aturan cosinus untuk ∠ADC, lalu jumlahkan luas kedua segitiga."],"wrongEn":"Do not try to solve triangle ADC before finding the shared diagonal AC.","wrongId":"Jangan mencoba menyelesaikan segitiga ADC sebelum menemukan diagonal bersama AC.","solutionEn":"AC≈9.28. Then cosine rule in ADC gives ∠ADC≈55.8°. The two triangle areas sum to approximately 77.8.","solutionId":"AC≈9,28. Lalu aturan cosinus pada ADC memberi ∠ADC≈55,8°. Jumlah luas kedua segitiga kira-kira 77,8.","strategyEn":"Gateway diagonal","strategyId":"Diagonal penghubung"},"H6":{"id":"H6","level":"challenge","family":"reverse-area","titleEn":"Area with two possible angles","titleId":"Luas dengan dua kemungkinan sudut","textEn":"A triangle has sides 10 cm and 14 cm and area 49 cm². Find all possible included angles and the corresponding third side for each triangle.","textId":"Sebuah segitiga memiliki sisi 10 cm dan 14 cm serta luas 49 cm². Tentukan semua kemungkinan sudut apit dan sisi ketiga untuk masing-masing segitiga.","fields":[{"labelEn":"Smaller angle (°)","labelId":"Sudut lebih kecil (°)","type":"number","answer":44.4,"tol":0.25},{"labelEn":"Third side 1 (cm)","labelId":"Sisi ketiga 1 (cm)","type":"number","answer":9.8,"tol":0.15},{"labelEn":"Larger angle (°)","labelId":"Sudut lebih besar (°)","type":"number","answer":135.6,"tol":0.25},{"labelEn":"Third side 2 (cm)","labelId":"Sisi ketiga 2 (cm)","type":"number","answer":22.3,"tol":0.2}],"hintsEn":["Use the area formula in reverse.","49=½(10)(14)sinC, so sinC=0.7.","Use both C and 180°−C, then cosine rule for each third side."],"hintsId":["Gunakan rumus luas secara terbalik.","49=½(10)(14)sinC, sehingga sinC=0,7.","Gunakan C dan 180°−C, lalu aturan cosinus untuk setiap sisi ketiga."],"wrongEn":"The same sine value can correspond to an acute and an obtuse included angle.","wrongId":"Nilai sinus yang sama dapat bersesuaian dengan sudut apit lancip maupun tumpul.","solutionEn":"C≈44.4° or 135.6°. The corresponding third sides are approximately 9.80 cm and 22.3 cm.","solutionId":"C≈44,4° atau 135,6°. Sisi ketiga yang bersesuaian kira-kira 9,80 cm dan 22,3 cm.","strategyEn":"Reverse-area ambiguity","strategyId":"Dua kemungkinan dari luas terbalik"},"H7":{"id":"H7","level":"challenge","family":"similarity","titleEn":"Similarity + trigonometry","titleId":"Kesebangunan + trigonometri","textEn":"AB=8, AC=11 and ∠BAC=52°. Triangle DEF is similar to ABC with A↔D, B↔E, C↔F. The area of DEF is three times the area of ABC. Find the linear scale factor, the three side lengths of DEF and its perimeter.","textId":"AB=8, AC=11, dan ∠BAC=52°. Segitiga DEF sebangun dengan ABC dengan A↔D, B↔E, C↔F. Luas DEF tiga kali luas ABC. Tentukan faktor skala linear, ketiga sisi DEF, dan kelilingnya.","fields":[{"labelEn":"Scale factor","labelId":"Faktor skala","type":"number","answer":1.7320508075688772,"tol":0.03},{"labelEn":"DE","labelId":"DE","type":"number","answer":13.9,"tol":0.2},{"labelEn":"DF","labelId":"DF","type":"number","answer":19.1,"tol":0.2},{"labelEn":"EF","labelId":"EF","type":"number","answer":15.2,"tol":0.25},{"labelEn":"Perimeter","labelId":"Keliling","type":"number","answer":48.1,"tol":0.3}],"hintsEn":["Area scale factor 3 means linear scale factor √3.","First use cosine rule to find BC in triangle ABC.","Multiply all three corresponding sides by √3."],"hintsId":["Faktor skala luas 3 berarti faktor skala linear √3.","Cari BC pada segitiga ABC dengan aturan cosinus terlebih dahulu.","Kalikan ketiga sisi bersesuaian dengan √3."],"wrongEn":"Do not use 3 as the linear scale factor; area scales by the square of the length scale.","wrongId":"Jangan gunakan 3 sebagai faktor skala linear; luas berskala dengan kuadrat faktor panjang.","solutionEn":"k=√3. BC≈8.75, so DEF has side lengths about 13.9, 19.1 and 15.2, giving perimeter≈48.1.","solutionId":"k=√3. BC≈8,75, sehingga sisi-sisi DEF kira-kira 13,9; 19,1; dan 15,2, dengan keliling≈48,1.","strategyEn":"Area-to-length scaling","strategyId":"Skala luas ke panjang"},"H8":{"id":"H8","level":"challenge","family":"circle-trig","titleEn":"Circle, chord and radians","titleId":"Lingkaran, tali busur, dan radian","textEn":"A circle has radius 8 cm and a chord of length 12 cm. Let θ be the minor central angle. Find θ in degrees and radians, the minor arc length and the minor segment area.","textId":"Sebuah lingkaran berjari-jari 8 cm memiliki tali busur panjang 12 cm. Misalkan θ adalah sudut pusat minor. Tentukan θ dalam derajat dan radian, panjang busur minor, dan luas tembereng minor.","fields":[{"labelEn":"θ (°)","labelId":"θ (°)","type":"number","answer":97.2,"tol":0.25},{"labelEn":"θ (rad)","labelId":"θ (rad)","type":"number","answer":1.696,"tol":0.015},{"labelEn":"Arc length (cm)","labelId":"Panjang busur (cm)","type":"number","answer":13.6,"tol":0.15},{"labelEn":"Segment area (cm²)","labelId":"Luas tembereng (cm²)","type":"number","answer":22.5,"tol":0.25}],"hintsEn":["Bisect the chord to create a right triangle.","sin(θ/2)=6/8.","Once θ is known in radians, use s=rθ and segment=½r²(θ−sinθ)."],"hintsId":["Bagi dua tali busur untuk membentuk segitiga siku-siku.","sin(θ/2)=6/8.","Setelah θ diketahui dalam radian, gunakan s=rθ dan tembereng=½r²(θ−sinθ)."],"wrongEn":"Do not use degrees inside the circular-measure formulas s=rθ or ½r²(θ−sinθ).","wrongId":"Jangan gunakan derajat di dalam rumus ukuran lingkaran s=rθ atau ½r²(θ−sinθ).","solutionEn":"θ≈97.2°≈1.696 rad. Arc length≈13.6 cm and minor segment area≈22.5 cm².","solutionId":"θ≈97,2°≈1,696 rad. Panjang busur≈13,6 cm dan luas tembereng minor≈22,5 cm².","strategyEn":"Chord-to-angle bridge","strategyId":"Tali busur menuju sudut"},"H9":{"id":"H9","level":"challenge","family":"bearing","titleEn":"Reconstruct a bearing","titleId":"Merekonstruksi bearing","textEn":"From A, AB=15 km on bearing 050°. Point C is 20 km from A and BC=13 km. C lies clockwise from ray AB. Find the bearing of C from A.","textId":"Dari A, AB=15 km pada bearing 050°. Titik C berjarak 20 km dari A dan BC=13 km. C berada searah jarum jam dari sinar AB. Tentukan bearing C dari A.","fields":[{"labelEn":"Bearing (°)","labelId":"Bearing (°)","type":"number","answer":91,"tol":0.6}],"hintsEn":["The side lengths form triangle ABC, so find ∠BAC first.","Use cosine rule in the 13-15-20 triangle.","Because C is clockwise from ray AB, add ∠BAC to 050°."],"hintsId":["Panjang-panjang sisi membentuk segitiga ABC, jadi cari ∠BAC terlebih dahulu.","Gunakan aturan cosinus pada segitiga 13-15-20.","Karena C searah jarum jam dari sinar AB, tambahkan ∠BAC pada 050°."],"wrongEn":"The clockwise-side condition tells you which of the two possible directions to use.","wrongId":"Syarat “searah jarum jam” menentukan arah mana yang harus dipilih.","solutionEn":"∠BAC≈40.5°, so the bearing is 050°+40.5°≈091°.","solutionId":"∠BAC≈40,5°, sehingga bearingnya 050°+40,5°≈091°.","strategyEn":"Reverse bearing reconstruction","strategyId":"Rekonstruksi bearing"},"H10":{"id":"H10","level":"challenge","family":"feasibility","titleEn":"Does the triangle exist?","titleId":"Apakah segitiganya ada?","textEn":"A=25°, a=4 and b=10. Determine whether a triangle exists. Give an algebraic/trigonometric and a geometric justification.","textId":"A=25°, a=4, dan b=10. Tentukan apakah segitiga dapat terbentuk. Berikan alasan aljabar/trigonometri dan alasan geometri.","fields":[{"labelEn":"Number of triangles","labelId":"Jumlah segitiga","type":"select","answer":"no","options":[{"value":"no","en":"No triangle","id":"Tidak ada segitiga"},{"value":"one","en":"One triangle","id":"Satu segitiga"},{"value":"two","en":"Two triangles","id":"Dua segitiga"}]},{"labelEn":"Critical height b sinA","labelId":"Tinggi kritis b sinA","type":"number","answer":4.23,"tol":0.06}],"hintsEn":["Try the sine rule: sinB = b sinA / a.","If the value exceeds 1, no real angle B exists.","Geometrically compare the critical height b sinA with side a."],"hintsId":["Coba aturan sinus: sinB = b sinA / a.","Jika nilainya melebihi 1, tidak ada sudut nyata B.","Secara geometri bandingkan tinggi kritis b sinA dengan sisi a."],"wrongEn":"If the required perpendicular height is larger than side a, the side cannot reach the ray.","wrongId":"Jika tinggi tegak lurus yang diperlukan lebih panjang daripada sisi a, sisi tersebut tidak dapat mencapai sinar.","solutionEn":"sinB=10sin25°/4≈1.06>1, so no triangle exists. Geometrically, the critical height 10sin25°≈4.23 is greater than a=4.","solutionId":"sinB=10sin25°/4≈1,06>1, sehingga tidak ada segitiga. Secara geometri, tinggi kritis 10sin25°≈4,23 lebih besar daripada a=4.","strategyEn":"Feasibility test","strategyId":"Uji kemungkinan"},"A1":{"id":"A1","level":"advanced","family":"triangulation","titleEn":"Triangulation","titleId":"Triangulasi","textEn":"Observation points A and B are 120 m apart. Target C lies on the same side of AB and ∠CAB=53°, ∠CBA=68°. Find AC, BC and the perpendicular distance from C to AB.","textId":"Titik pengamatan A dan B berjarak 120 m. Target C berada pada sisi yang sama dari AB dan ∠CAB=53°, ∠CBA=68°. Tentukan AC, BC, dan jarak tegak lurus C ke AB.","fields":[{"labelEn":"AC (m)","labelId":"AC (m)","type":"number","answer":130,"tol":1},{"labelEn":"BC (m)","labelId":"BC (m)","type":"number","answer":112,"tol":1},{"labelEn":"Perpendicular distance (m)","labelId":"Jarak tegak lurus (m)","type":"number","answer":104,"tol":1}],"hintsEn":["Find angle C first.","AB=120 is opposite angle C, giving the complete sine-rule pair.","After AC is known, the perpendicular distance is AC sin53°."],"hintsId":["Cari sudut C terlebih dahulu.","AB=120 berada di depan sudut C, sehingga menjadi pasangan lengkap aturan sinus.","Setelah AC diketahui, jarak tegak lurus adalah AC sin53°."],"wrongEn":"The perpendicular distance is not a new triangle problem until one sloping side has been found.","wrongId":"Jarak tegak lurus belum dapat dihitung sampai salah satu sisi miring ditemukan.","solutionEn":"C=59°. Sine rule gives AC≈130 m and BC≈112 m. Perpendicular distance≈AC sin53°≈104 m.","solutionId":"C=59°. Aturan sinus memberi AC≈130 m dan BC≈112 m. Jarak tegak lurus≈AC sin53°≈104 m.","strategyEn":"Triangulation chain","strategyId":"Rantai triangulasi"},"A2":{"id":"A2","level":"advanced","family":"multi-triangle","titleEn":"Multi-stage quadrilateral","titleId":"Segiempat bertahap","textEn":"Diagonal BD divides quadrilateral ABCD. In △ABD, AB=7, AD=10, ∠BAD=65°. Also BC=9 and CD=12. Find BD, ∠BCD and the total area of ABCD.","textId":"Diagonal BD membagi segiempat ABCD. Pada △ABD, AB=7, AD=10, ∠BAD=65°. Selain itu BC=9 dan CD=12. Tentukan BD, ∠BCD, dan luas total ABCD.","fields":[{"labelEn":"BD","labelId":"BD","type":"number","answer":9.48,"tol":0.12},{"labelEn":"∠BCD (°)","labelId":"∠BCD (°)","type":"number","answer":51.3,"tol":0.25},{"labelEn":"Total area","labelId":"Luas total","type":"number","answer":73.8,"tol":0.4}],"hintsEn":["Triangle ABD is solvable first by SAS.","The diagonal BD becomes the third side of triangle BCD.","Then use SSS cosine rule for ∠BCD and add the two triangle areas."],"hintsId":["Segitiga ABD dapat diselesaikan lebih dulu dengan SAS.","Diagonal BD menjadi sisi ketiga segitiga BCD.","Lalu gunakan aturan cosinus SSS untuk ∠BCD dan jumlahkan luas kedua segitiga."],"wrongEn":"The gateway quantity is BD; do not start in triangle BCD before it is known.","wrongId":"Besaran penghubungnya adalah BD; jangan mulai dari segitiga BCD sebelum BD diketahui.","solutionEn":"BD≈9.48. Then ∠BCD≈51.3°. The two triangle areas sum to approximately 73.8.","solutionId":"BD≈9,48. Lalu ∠BCD≈51,3°. Jumlah luas kedua segitiga kira-kira 73,8.","strategyEn":"Multi-stage dependency","strategyId":"Ketergantungan bertahap"},"A3":{"id":"A3","level":"advanced","family":"bearing","titleEn":"Three-leg bearing journey","titleId":"Perjalanan bearing tiga tahap","textEn":"A survey vehicle travels 20 km on 030°, then 15 km on 120°, then 12 km on 210°. Find total east-west displacement, total north-south displacement, straight-line distance from the start and final bearing.","textId":"Sebuah kendaraan survei bergerak 20 km pada 030°, lalu 15 km pada 120°, lalu 12 km pada 210°. Tentukan perpindahan total timur-barat, perpindahan total utara-selatan, jarak lurus dari titik awal, dan bearing akhir.","fields":[{"labelEn":"East displacement (km)","labelId":"Perpindahan timur (km)","type":"number","answer":17.0,"tol":0.15},{"labelEn":"South displacement (km)","labelId":"Perpindahan selatan (km)","type":"number","answer":0.572,"tol":0.03},{"labelEn":"Distance from start (km)","labelId":"Jarak dari awal (km)","type":"number","answer":17.0,"tol":0.15},{"labelEn":"Final bearing (°)","labelId":"Bearing akhir (°)","type":"number","answer":92,"tol":0.5}],"hintsEn":["Resolve every leg into East and North components.","Add signed components before finding the resultant.","Use atan2(E,N) or an equivalent quadrant-aware bearing calculation."],"hintsId":["Uraikan setiap tahap menjadi komponen Timur dan Utara.","Jumlahkan komponen bertanda sebelum mencari resultan.","Gunakan atan2(E,N) atau perhitungan bearing lain yang memperhatikan kuadran."],"wrongEn":"Do not add travel distances directly; add vector components.","wrongId":"Jangan menjumlahkan jarak perjalanan secara langsung; jumlahkan komponen vektornya.","solutionEn":"E≈17.0 km east and N≈−0.572 km, so 0.572 km south. Resultant distance≈17.0 km and bearing≈092°.","solutionId":"E≈17,0 km ke timur dan N≈−0,572 km, jadi 0,572 km ke selatan. Jarak resultan≈17,0 km dan bearing≈092°.","strategyEn":"Vector-style bearing synthesis","strategyId":"Sintesis bearing berbasis komponen"},"A4":{"id":"A4","level":"advanced","family":"ambiguity","titleEn":"Two possible bearings","titleId":"Dua kemungkinan bearing","textEn":"From A, AB=10 km on bearing 060°. Point C satisfies AC=14 km and BC=8 km. No information is given about which side of AB contains C. Find all possible bearings of C from A.","textId":"Dari A, AB=10 km pada bearing 060°. Titik C memenuhi AC=14 km dan BC=8 km. Tidak diberikan informasi di sisi mana terhadap AB titik C berada. Tentukan semua kemungkinan bearing C dari A.","fields":[{"labelEn":"Bearing 1 (°)","labelId":"Bearing 1 (°)","type":"number","answer":26,"tol":0.5},{"labelEn":"Bearing 2 (°)","labelId":"Bearing 2 (°)","type":"number","answer":94,"tol":0.5}],"hintsEn":["Use cosine rule to find ∠BAC from sides 10,14,8.","The triangle can be reflected across ray AB.","Apply ±∠BAC to the 060° bearing."],"hintsId":["Gunakan aturan cosinus untuk mencari ∠BAC dari sisi 10,14,8.","Segitiga dapat dicerminkan terhadap sinar AB.","Gunakan ±∠BAC terhadap bearing 060°."],"wrongEn":"The missing side-of-AB condition means both mirror orientations must be retained.","wrongId":"Karena sisi terhadap AB tidak ditentukan, kedua orientasi cermin harus dipertahankan.","solutionEn":"∠BAC≈34.0°. Therefore the two bearings are 060°−34°≈026° and 060°+34°≈094°.","solutionId":"∠BAC≈34,0°. Maka kedua bearing adalah 060°−34°≈026° dan 060°+34°≈094°.","strategyEn":"Mirror bearing configurations","strategyId":"Konfigurasi bearing cermin"},"A5":{"id":"A5","level":"advanced","family":"parameter","titleEn":"Parameter from geometry","titleId":"Parameter dari geometri","textEn":"A triangle has two sides x+2 and x+5 with included angle 60°. The third side is 7. Find all algebraic x-values, the geometrically valid value, the area and the perimeter.","textId":"Sebuah segitiga memiliki dua sisi x+2 dan x+5 dengan sudut apit 60°. Sisi ketiganya 7. Tentukan semua nilai x secara aljabar, nilai yang valid secara geometri, luas, dan keliling.","fields":[{"labelEn":"Valid x","labelId":"x valid","type":"number","answer":3,"tol":0.01},{"labelEn":"Area","labelId":"Luas","type":"number","answer":17.3205,"tol":0.08},{"labelEn":"Perimeter","labelId":"Keliling","type":"number","answer":20,"tol":0.05}],"hintsEn":["Translate the geometric condition with the cosine rule.","Solve the resulting quadratic; it has two algebraic roots.","Reject the root that makes side lengths invalid, then use ½ab sin60° for area."],"hintsId":["Terjemahkan syarat geometri dengan aturan cosinus.","Selesaikan persamaan kuadrat yang terbentuk; ada dua akar aljabar.","Tolak akar yang membuat panjang sisi tidak valid, lalu gunakan ½ab sin60° untuk luas."],"wrongEn":"An algebraic root is not automatically a geometric solution; check positive side lengths and the original triangle.","wrongId":"Akar aljabar belum tentu solusi geometri; cek panjang sisi positif dan segitiga asal.","solutionEn":"Cosine rule gives (x−3)(x+10)=0. Only x=3 is valid, giving sides 5,8,7. Area=10√3≈17.32 and perimeter=20.","solutionId":"Aturan cosinus memberi (x−3)(x+10)=0. Hanya x=3 yang valid, sehingga sisinya 5,8,7. Luas=10√3≈17,32 dan keliling=20.","strategyEn":"Parameter validity","strategyId":"Keabsahan parameter"},"A6":{"id":"A6","level":"advanced","family":"circle-trig","titleEn":"Chord, tangents and circular measure","titleId":"Tali busur, garis singgung, dan ukuran lingkaran","textEn":"A circle has centre O, radius 10 cm and chord AB=12 cm. Tangents at A and B meet at external point P. Let θ=∠AOB be the minor central angle. Find θ in radians, PA, the perimeter of the region bounded by PA, PB and minor arc AB, and its area.","textId":"Sebuah lingkaran berpusat O, berjari-jari 10 cm, dan memiliki tali busur AB=12 cm. Garis singgung di A dan B berpotongan di titik luar P. Misalkan θ=∠AOB adalah sudut pusat minor. Tentukan θ dalam radian, PA, keliling daerah yang dibatasi PA, PB, dan busur minor AB, serta luasnya.","fields":[{"labelEn":"θ (rad)","labelId":"θ (rad)","type":"number","answer":1.287,"tol":0.015},{"labelEn":"PA (cm)","labelId":"PA (cm)","type":"number","answer":7.5,"tol":0.08},{"labelEn":"Perimeter (cm)","labelId":"Keliling (cm)","type":"number","answer":27.9,"tol":0.2},{"labelEn":"Area (cm²)","labelId":"Luas (cm²)","type":"number","answer":10.6,"tol":0.25}],"hintsEn":["Bisect chord AB: half-chord is 6 and radius is 10.","Use sin(θ/2)=3/5 to find θ.","Use tangent geometry to find PA, then combine two tangents with the minor arc; area is the tangent kite minus the sector."],"hintsId":["Bagi dua tali busur AB: setengah tali busur 6 dan jari-jari 10.","Gunakan sin(θ/2)=3/5 untuk mencari θ.","Gunakan geometri garis singgung untuk mencari PA, lalu gabungkan dua garis singgung dengan busur minor; luas adalah luas layang-layang singgung dikurangi juring."],"wrongEn":"Do not let the solution-state tangent lengths or central angle appear in the initial diagram.","wrongId":"Jangan biarkan panjang garis singgung atau sudut pusat hasil perhitungan muncul pada diagram awal.","solutionEn":"θ=2sin⁻¹(3/5)≈1.287 rad. PA=7.5 cm. Perimeter=15+10θ≈27.9 cm and area=75−50θ≈10.6 cm².","solutionId":"θ=2sin⁻¹(3/5)≈1,287 rad. PA=7,5 cm. Keliling=15+10θ≈27,9 cm dan luas=75−50θ≈10,6 cm².","strategyEn":"Circle-trig synthesis","strategyId":"Sintesis lingkaran-trigonometri"},"A7":{"id":"A7","level":"advanced","family":"proof","titleEn":"Prove the angle classification","titleId":"Buktikan klasifikasi sudut","textEn":"Using the cosine rule, relate c² to a²+b² when C is acute, right, and obtuse.","textId":"Dengan aturan cosinus, hubungkan c² dengan a²+b² ketika C lancip, siku-siku, dan tumpul.","fields":[{"labelEn":"If C<90°","labelId":"Jika C<90°","type":"select","answer":"lt","options":[{"value":"lt","en":"c² < a² + b²","id":"c² < a² + b²"},{"value":"eq","en":"c² = a² + b²","id":"c² = a² + b²"},{"value":"gt","en":"c² > a² + b²","id":"c² > a² + b²"}]},{"labelEn":"If C=90°","labelId":"Jika C=90°","type":"select","answer":"eq","options":[{"value":"lt","en":"c² < a² + b²","id":"c² < a² + b²"},{"value":"eq","en":"c² = a² + b²","id":"c² = a² + b²"},{"value":"gt","en":"c² > a² + b²","id":"c² > a² + b²"}]},{"labelEn":"If C>90°","labelId":"Jika C>90°","type":"select","answer":"gt","options":[{"value":"lt","en":"c² < a² + b²","id":"c² < a² + b²"},{"value":"eq","en":"c² = a² + b²","id":"c² = a² + b²"},{"value":"gt","en":"c² > a² + b²","id":"c² > a² + b²"}]}],"hintsEn":["Start from c²=a²+b²−2ab cosC.","The sign of cosC changes at 90°.","For acute C, cosC>0; at 90°, cosC=0; for obtuse C, cosC<0."],"hintsId":["Mulai dari c²=a²+b²−2ab cosC.","Tanda cosC berubah pada 90°.","Untuk C lancip, cosC>0; pada 90°, cosC=0; untuk C tumpul, cosC<0."],"wrongEn":"Focus on the sign of the term −2ab cosC rather than calculating an angle.","wrongId":"Fokus pada tanda suku −2ab cosC, bukan menghitung sudut.","solutionEn":"If C<90°, cosC>0 so c²<a²+b². If C=90°, equality holds. If C>90°, cosC<0 so c²>a²+b². This is a fast plausibility check.","solutionId":"Jika C<90°, cosC>0 sehingga c²<a²+b². Jika C=90°, berlaku sama dengan. Jika C>90°, cosC<0 sehingga c²>a²+b². Ini menjadi cek kewajaran yang cepat.","strategyEn":"Proof from sign of cosine","strategyId":"Pembuktian dari tanda cosinus"},"A8":{"id":"A8","level":"advanced","family":"triangulation","titleEn":"Bearings from two stations","titleId":"Bearing dari dua stasiun","textEn":"A and B are 50 km apart, with B due east of A. C is observed on bearing 035° from A and bearing 300° from B. Find ∠CAB, ∠CBA, AC, BC and the perpendicular distance from C to AB.","textId":"A dan B berjarak 50 km, dengan B tepat di timur A. C diamati pada bearing 035° dari A dan bearing 300° dari B. Tentukan ∠CAB, ∠CBA, AC, BC, dan jarak tegak lurus C ke AB.","fields":[{"labelEn":"∠CAB (°)","labelId":"∠CAB (°)","type":"number","answer":55,"tol":0.1},{"labelEn":"∠CBA (°)","labelId":"∠CBA (°)","type":"number","answer":30,"tol":0.1},{"labelEn":"AC (km)","labelId":"AC (km)","type":"number","answer":25.1,"tol":0.2},{"labelEn":"BC (km)","labelId":"BC (km)","type":"number","answer":41.1,"tol":0.25},{"labelEn":"Height to AB (km)","labelId":"Jarak tegak lurus ke AB (km)","type":"number","answer":20.6,"tol":0.2}],"hintsEn":["Convert each bearing to the internal baseline angle first.","Because AB is due east, ∠CAB=90°−35° and ∠CBA=300°−270°.","Then use sine rule with AB=50, followed by AC sin55° for the height."],"hintsId":["Ubah setiap bearing menjadi sudut dalam terhadap garis dasar terlebih dahulu.","Karena AB tepat ke timur, ∠CAB=90°−35° dan ∠CBA=300°−270°.","Lalu gunakan aturan sinus dengan AB=50, diikuti AC sin55° untuk tinggi."],"wrongEn":"Do not insert the raw bearings directly as triangle angles.","wrongId":"Jangan memasukkan bearing mentah langsung sebagai sudut segitiga.","solutionEn":"∠CAB=55°, ∠CBA=30°, so C=95°. Sine rule gives AC≈25.1 km and BC≈41.1 km. Height≈AC sin55°≈20.6 km.","solutionId":"∠CAB=55°, ∠CBA=30°, sehingga C=95°. Aturan sinus memberi AC≈25,1 km dan BC≈41,1 km. Tinggi≈AC sin55°≈20,6 km.","strategyEn":"Two-station triangulation","strategyId":"Triangulasi dua stasiun"},"A9":{"id":"A9","level":"advanced","family":"bearing-elevation","titleEn":"Ground bearings + elevation","titleId":"Bearing tanah + elevasi","textEn":"A and B are 50 m apart, with B on bearing 090° from A. The foot T of a vertical tower is on bearing 040° from A and 330° from B. The angle of elevation from A to the top U is 30°. Find AT, BT, tower height TU and the angle of elevation from B to U.","textId":"A dan B berjarak 50 m, dengan B pada bearing 090° dari A. Kaki T sebuah menara vertikal berada pada bearing 040° dari A dan 330° dari B. Sudut elevasi dari A ke puncak U adalah 30°. Tentukan AT, BT, tinggi menara TU, dan sudut elevasi dari B ke U.","fields":[{"labelEn":"AT (m)","labelId":"AT (m)","type":"number","answer":46.1,"tol":0.3},{"labelEn":"BT (m)","labelId":"BT (m)","type":"number","answer":40.8,"tol":0.3},{"labelEn":"TU (m)","labelId":"TU (m)","type":"number","answer":26.6,"tol":0.3},{"labelEn":"Elevation from B (°)","labelId":"Elevasi dari B (°)","type":"number","answer":33.1,"tol":0.3}],"hintsEn":["Solve the ground triangle ABT before using elevation.","Convert bearings to ground-triangle angles: 50°, 60°, 70°.","Use sine rule for AT and BT, then TU=AT tan30° and tanβ=TU/BT."],"hintsId":["Selesaikan segitiga tanah ABT sebelum menggunakan elevasi.","Ubah bearing menjadi sudut segitiga tanah: 50°, 60°, 70°.","Gunakan aturan sinus untuk AT dan BT, lalu TU=AT tan30° dan tanβ=TU/BT."],"wrongEn":"The 3D-looking problem is a ground triangle followed by two right-triangle elevation calculations.","wrongId":"Soal yang tampak 3D ini sebenarnya berupa segitiga tanah lalu dua perhitungan elevasi segitiga siku-siku.","solutionEn":"Ground triangle gives AT≈46.1 m and BT≈40.8 m. TU=AT tan30°≈26.6 m. Then elevation from B≈tan⁻¹(26.6/40.8)≈33.1°.","solutionId":"Segitiga tanah memberi AT≈46,1 m dan BT≈40,8 m. TU=AT tan30°≈26,6 m. Lalu sudut elevasi dari B≈tan⁻¹(26,6/40,8)≈33,1°.","strategyEn":"Ground-to-elevation synthesis","strategyId":"Sintesis tanah ke elevasi"},"A10":{"id":"A10","level":"advanced","family":"reconstruction","titleEn":"Reconstruct a triangle","titleId":"Merekonstruksi segitiga","textEn":"Two sides of a triangle differ by 2 cm. The angle between them is 60°. The area is 12√3 cm². Find the two enclosing sides, the third side exactly, and the exact perimeter. Show the positive geometric solution is unique.","textId":"Dua sisi sebuah segitiga berbeda 2 cm. Sudut di antaranya 60°. Luasnya 12√3 cm². Tentukan kedua sisi pengapit, sisi ketiga secara eksak, dan keliling eksak. Tunjukkan bahwa solusi geometri positifnya tunggal.","fields":[{"labelEn":"Shorter side (cm)","labelId":"Sisi lebih pendek (cm)","type":"number","answer":6,"tol":0.01},{"labelEn":"Longer side (cm)","labelId":"Sisi lebih panjang (cm)","type":"number","answer":8,"tol":0.01},{"labelEn":"Third side (cm)","labelId":"Sisi ketiga (cm)","type":"number","answer":7.211102550927978,"tol":0.05},{"labelEn":"Perimeter (cm)","labelId":"Keliling (cm)","type":"number","answer":21.21110255092798,"tol":0.06}],"hintsEn":["Let the shorter side be x and the longer x+2.","Use the area condition before the cosine rule.","The area equation gives x(x+2)=48; reject the negative root, then use cosine rule for the third side."],"hintsId":["Misalkan sisi lebih pendek x dan sisi lebih panjang x+2.","Gunakan syarat luas sebelum aturan cosinus.","Persamaan luas memberi x(x+2)=48; tolak akar negatif, lalu gunakan aturan cosinus untuk sisi ketiga."],"wrongEn":"The uniqueness comes from the area equation plus the requirement that side lengths be positive.","wrongId":"Ketunggalan berasal dari persamaan luas ditambah syarat bahwa panjang sisi harus positif.","solutionEn":"x=6 is the unique positive solution, so the enclosing sides are 6 and 8. Cosine rule gives c=2√13≈7.21 cm and perimeter=14+2√13≈21.2 cm.","solutionId":"x=6 adalah satu-satunya solusi positif, sehingga sisi pengapitnya 6 dan 8. Aturan cosinus memberi c=2√13≈7,21 cm dan keliling=14+2√13≈21,2 cm.","strategyEn":"Reverse reconstruction","strategyId":"Rekonstruksi terbalik"}};
const UNIT_BANK={"C":["C2","C3","H2","A1"],"D":["C3","H2","H6","H10","A4"],"E":["C4","C5","H1","H5","A2","A5","A7"],"G":["C6","C7","H6","H7","A10"],"H":["C8","C10","H3","H9","A3","A4","A8","A9"],"I":["C9","H4","A9"],"J":["H1","H5","A1","A2","A8","A9"],"L":["H10","A5","A7","A10"],"N":["H7","H8","A6"],"O":["H5","H8","H10","A1","A2","A3","A4","A5","A6","A7","A8","A9","A10"],"S":["C1","C2","C3","C4","C5","C6","C7","C8","C9","C10","H1","H2","H3","H4","H5","H6","H7","H8","H9","H10","A1","A2","A3","A4","A5","A6","A7","A8","A9","A10"]};
const FAMILY_LABELS={"method":{"en":"Method selection","id":"Pemilihan metode"},"sine-side":{"en":"Sine-rule side","id":"Sisi dengan aturan sinus"},"sine-angle":{"en":"Sine-rule angle","id":"Sudut dengan aturan sinus"},"ambiguity":{"en":"Ambiguity / multiple configurations","id":"Dua kemungkinan / beberapa konfigurasi"},"cosine-side":{"en":"Cosine-rule side","id":"Sisi dengan aturan cosinus"},"cosine-angle":{"en":"Cosine-rule angle","id":"Sudut dengan aturan cosinus"},"area":{"en":"Triangle area","id":"Luas segitiga"},"reverse-area":{"en":"Reverse area","id":"Luas terbalik"},"bearing":{"en":"Bearings","id":"Bearing"},"elevation":{"en":"Elevation / depression","id":"Elevasi / depresi"},"multi-triangle":{"en":"Multi-triangle","id":"Beberapa segitiga"},"similarity":{"en":"Similarity","id":"Kesebangunan"},"circle-trig":{"en":"Circle + trigonometry","id":"Lingkaran + trigonometri"},"feasibility":{"en":"Feasibility","id":"Kemungkinan geometri"},"triangulation":{"en":"Triangulation","id":"Triangulasi"},"parameter":{"en":"Parameter / algebra","id":"Parameter / aljabar"},"proof":{"en":"Proof / justification","id":"Bukti / alasan"},"bearing-elevation":{"en":"Bearings + elevation","id":"Bearing + elevasi"},"reconstruction":{"en":"Reconstruction","id":"Rekonstruksi"}};
